function WeekTasksMainDialog:LoadScene()
    if not isNull(self.sceneGo) then
        printInfo("sceneGo not null")
        return
    end
    local co = cs_coroutine.start(function ()
        xTry(function()
            local loader = ResourceModule.LoadBundleAsync("Camera/Prefab/WeekMisson_TL.prefab", nil, true)
            while not loader.IsSuccess do
                cs_coroutine.yield_return()
            end
            if not loader.IsError then
                local dynamicNodeGo = GameObject.Find("DynamicNode")
                local go = loader:Instantiate(dynamicNodeGo.transform, false)
                table.insert(self.loaderList, loader)
                go.name = "WeekTasksMainScene"
                self.cameraAnimDirector = go.gameObject:GetComponent(typeof(PlayableDirector))
                self.cameraAnim = go.transform:Find("WeekMisson_came")
                KTool.SetActive(self.cameraAnim, false)
                self.cam = go.transform:Find("WeekMisson/Main Camera")
                KTool.SetActive(self.cam, false)
                self.ballPrefabSpecial = go.transform:Find("WeekMisson/bg_prizeball01")--找到普通和特殊扭蛋小球Prefab
                self.ballPrefabNormal = go.transform:Find("WeekMisson/bg_prizeball02")--找到普通和特殊扭蛋小球Prefab
                ---由于这边路径可能会变动，所以直接写成查找完整路径，便于修改
                self.VMachine01 = go.transform:Find("WeekMisson/bg_vmachine01/bg_vmachine01/vmachine01/VMachine01")
                self.VMachine01_board01 = go.transform:Find("WeekMisson/bg_vmachine01/bg_vmachine01/vmachine01/VMachine01_board01")
                self.VMachine01TV01 = go.transform:Find("WeekMisson/bg_vmachine01/bg_vmachine01/vmachine01/VMachine01TV01")
                local uiTargetGo = go.transform:Find("WeekMisson/bg_vmachine01/UITargetPos")
                self.Time1 = uiTargetGo.transform:Find("Time1")
                self.Time2 = uiTargetGo.transform:Find("Time2")
                self.Board = uiTargetGo.transform:Find("Board")
                self:SetUIPosition()
                self.sceneGo = go
                for i = 1, 10 do--找到10个用于生成扭蛋小球的GameObject
                    if i <= 4 then--找到4个做旋转的GameObject
                        local rotateGo = go.transform:Find("WeekMisson/bg_vmachine01/bg_vmachine01/vmachine01/Play0"..i)
                        if not rotateGo then
                            printError("WeekTasksMainScene找不到用于旋转的四个gameObject!!")
                            return
                        end
                        table.insert(self.rotateGoList, rotateGo)
                    end
                    local suffix = i < 10 and "0"..i or i--小于10在前面补0
                    local ballPointGo = go.transform:Find("WeekMisson/bg_vmachine01/ballPosition/ball"..suffix)
                    if not ballPointGo then
                        printError("WeekTasksMainScene找不到用于初始化扭蛋小球的10个位置的gameObject!!")
                        return
                    end
                    table.insert(self.ballPointGoList, ballPointGo)
                end

            end
            loader:Release()
            loader = nil
        end
        )
    end)
    table.insert(self.loadCoList, co)
    return co
end

