function WeekTasksMainDialog:FreshUI()
    self:FreshLeftContent()
    self:FreshRightContent()
end

function WeekTasksMainDialog:FreshLeftContent()
    self.TextNumberDesc.text = string.format(" <color=#04eff3><size=36>%s</size></color>/%s", weekGachaponComponent.callTaskRewardsAvailableNum - weekGachaponComponent.callTaskRewardsNum, weekGachaponComponent.callTaskRewardsAvailableNum)
    local isGetAllReward = weekGachaponComponent:IsGetAllReward()
    local curTime = os.time()
    if isGetAllReward then
        if isNull(self.Text1.Env) then
            self.Text1:Init()
        end

        self.Text1.Env:StartLeftSecond(weekGachaponComponent.callRewardTimeLeft - curTime, 3)
    else
        if isNull(self.Text2.Env) then
            self.Text2:Init()
        end
        self.Text2.Env:StartLeftSecond(weekGachaponComponent.callRewardTimeLeft - curTime, 3)
    end
    KTool.SetActive(self.SoldOut.transform, isGetAllReward)
    KTool.SetActive(self.Normal.transform, not isGetAllReward)
    KTool.SetActive(self.GashaponNewGroup.transform, not isGetAllReward)
    self:FreshMachineStatus(not isGetAllReward)
end

function WeekTasksMainDialog:FreshRightContent()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local serverTime      = playerComponent.playerDojo.serverTime
    local nowTime         = checkInt(TimeZoneUtils.UtcSeconds)
    local pastTime        = nowTime - serverTime
    local refreshTime     = playerComponent.playerDojo.dailyRefreshTime - pastTime
    self.TextNumber.Env:StartLeftSecond(refreshTime, 2)
    if not self.LoopListTasks.IsListViewInit then
        self.LoopListTasks:InitListView(#weekGachaponComponent.randomTaskList, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListTasks, #weekGachaponComponent.randomTaskList)
    end
end

